int height(Node *n) { return n ? n->h : 0; }
int balance(Node *n) { return n ? height(n->left) - height(n->right) : 0; }
void update(Node *n) { n->h = 1 + max(height(n->left), height(n->right)); }

Node *rotate_right(Node *y) {      //     y          x
  Node *x = y->left;               //    / \        / \
  y->left = x->right;              //   x   C  ->  A   y
  x->right = y;                    //  / \            / \
  update(y); update(x); return x;  // A   B          B   C
}
Node *rotate_left(Node *x) {
  Node *y = x->right;
  x->right = y->left; y->left = x;
  update(x); update(y); return y;
}

Node *insert(Node *n, int k) {
  if (!n) return new_node(k);
  if (k < n->key) n->left = insert(n->left, k);
  else if (k > n->key) n->right = insert(n->right, k);
  else return n;
  update(n);
  int b = balance(n);
  if (b > 1 && k < n->left->key)  return rotate_right(n);
  if (b < -1 && k > n->right->key) return rotate_left(n);
  if (b > 1 && k > n->left->key)  { n->left = rotate_left(n->left); return rotate_right(n); }
  if (b < -1 && k < n->right->key) { n->right = rotate_right(n->right); return rotate_left(n); }
  return n;
}
